const envelope = $input || {};
const text = (value) => (typeof value === 'string' ? value.trim() : '');
const envelopeKeys = new Set(['pluginId', 'widgetId', 'product', 'resource', 'submittedBy', 'submittedAt', 'action', 'fields']);
const unknownEnvelope = Object.keys(envelope).filter((key) => !envelopeKeys.has(key));
if (unknownEnvelope.length) throw new Error('unknown_envelope_fields:' + unknownEnvelope.join(','));
const product = text(envelope.product);
const resource = text(envelope.resource);
const submittedBy = text(envelope.submittedBy);
if (!submittedBy) throw new Error('submitted_by_required');
const fields = envelope.fields && typeof envelope.fields === 'object' && !Array.isArray(envelope.fields) ? envelope.fields : null;
if (!fields) throw new Error('fields_required');

if (product !== 'sos') throw new Error('unsupported_product');
if (resource !== 'sitrep') throw new Error('unsupported_resource');
const recordId = text(fields.sitrep_id);
if (!/^[A-Za-z0-9_@.:+-]{1,256}$/.test(recordId)) throw new Error('record_id_invalid');
const COUNT_FIELDS = ['casualties', 'deaths', 'injuries', 'missing', 'affected_people', 'evacuated_people', 'damaged_structures', 'destroyed_structures', 'rescued_people', 'resources_deployed'];
const allowed = new Set(['sitrep_id', 'summary', 'note', ...COUNT_FIELDS]);
const unknown = Object.keys(fields).filter((key) => !allowed.has(key));
if (unknown.length) throw new Error('unknown_fields:' + unknown.join(','));
const changes = {};
for (const name of COUNT_FIELDS) {
  const raw = fields[name];
  if (raw === undefined || raw === null || raw === '') continue;
  const num = typeof raw === 'number' ? raw : typeof raw === 'string' && raw.trim() && Number.isFinite(Number(raw)) ? Number(raw) : null;
  if (num === null || !Number.isInteger(num) || num < 0) throw new Error(name + '_non_negative_integer_required');
  changes[name] = num;
}
const summary = text(fields.summary);
if (summary) changes.summary = summary;
if (summary.length > 8000) throw new Error('summary_max_8000');
const note = text(fields.note);
if (note.length > 4000) throw new Error('note_max_4000');
const audit = {
  product, resource, operation: 'sitrep.delta', recordId,
  pluginId: text(envelope.pluginId), widgetId: text(envelope.widgetId),
  submittedBy, submittedAt: text(envelope.submittedAt) || $now,
};
return { recordId, encodedId: encodeURIComponent(recordId), changes, note, audit };

const response = $input || {};
const state = response.input;
const current = response.body;
if (response.statusCode !== 200 || !current || typeof current.data !== 'object' || !current.data) throw new Error('sitrep_not_found');
if (!Number.isInteger(current.version)) throw new Error('record_version_unavailable');
const sitrep = { ...current.data, id: String(current.data.id || current.id) };
const status = String(sitrep.status);
if (!['draft', 'review_pending', 'published', 'archived'].includes(status)) throw new Error('sitrep_status_invalid');
const amendsId = typeof sitrep.amends_sitrep_id === 'string' && sitrep.amends_sitrep_id.trim() ? sitrep.amends_sitrep_id.trim() : '';
return {
  sitrep, status, version: current.version,
  encodedId: state.encodedId, changes: state.changes, note: state.note,
  needsBase: amendsId ? true : false, encodedBaseId: amendsId ? encodeURIComponent(amendsId) : '',
  audit: state.audit, operation: state.operation,
};

const response = $input || {};
const state = response.input;
if (response.statusCode !== 200 || !response.body || typeof response.body.data !== 'object' || !response.body.data) throw new Error('sitrep_base_not_found');
const base = { ...response.body.data, id: String(response.body.data.id || response.body.id) };
return { ...state, base };

const state = $input || {};
const sitrep = state.sitrep;
const base = state.base || sitrep;
const changedFields = [];
for (const [name, to] of Object.entries(state.changes)) {
  const from = base[name] === undefined ? null : base[name];
  if (JSON.stringify(from) === JSON.stringify(to)) continue;
  changedFields.push({ field: name, from, to });
}
// A delta entry must be a real structural change, never a no-op write.
if (!changedFields.length) throw new Error('sitrep_delta_empty');
const baseRevision = typeof base.version === 'number' && Number.isFinite(base.version) && base.version !== 0 ? base.version : 1;
const currentRevision = typeof sitrep.version === 'number' && Number.isFinite(sitrep.version) && sitrep.version !== 0 ? sitrep.version : 1;
const mode = (state.status === 'published' || state.status === 'archived') ? 'revision' : 'append';
const deltaEntry = {
  action_type: 'update',
  changed_fields: changedFields,
  from_revision: baseRevision,
  to_revision: mode === 'revision' ? currentRevision + 1 : currentRevision,
  note: state.note || null,
  actor_id: state.audit.submittedBy,
  created_at: $now,
};
return { sitrep, status: state.status, version: state.version, deltaEntry, mode, currentRevision, encodedId: state.encodedId, audit: state.audit, operation: state.operation };

const state = $input || {};
if (state.mode !== 'revision') throw new Error('unexpected_delta_mode');
const sitrep = state.sitrep;
const millis = Date.parse($now);
const nowMs = Number.isFinite(millis) ? millis : 0;
const nonce = Math.random().toString(36).slice(2, 8).padEnd(6, '0');
const revisionId = 'sitrep-' + nowMs + '-' + nonce;
const revision = {
  ...sitrep,
  id: revisionId,
  status: 'draft',
  amends_sitrep_id: sitrep.id,
  version: state.currentRevision + 1,
  deltas: [state.deltaEntry],
  published_at: null,
  published_by: null,
  created_at: $now,
  updated_at: $now,
  author: state.audit.submittedBy || (typeof sitrep.author === 'string' ? sitrep.author : 'sos-operator'),
};
return { createBody: { id: revisionId, data: revision, publish: false }, sitrep, deltaEntry: state.deltaEntry };

const response = $input || {};
const state = response.input;
if (response.statusCode !== 201 && response.statusCode !== 200) throw new Error('sitrep_revision_create_failed');
const revisionId = response.body && response.body.id ? String(response.body.id) : String(state.createBody.id);
return {
  operation: 'sitrep.delta', mode: 'revision', revision_id: revisionId,
  amends_sitrep_id: state.sitrep.id, superseded_sitrep_id: state.sitrep.id,
  from_revision: state.deltaEntry.from_revision, to_revision: state.deltaEntry.to_revision,
  changed_fields: state.deltaEntry.changed_fields, status: 'draft', publish: false,
};

const state = $input || {};
if (state.mode !== 'append') throw new Error('unexpected_delta_mode');
const deltas = Array.isArray(state.sitrep.deltas) ? state.sitrep.deltas : [];
const next = { ...state.sitrep, deltas: [...deltas, state.deltaEntry], updated_at: $now };
return { body: { data: next, ifVersion: state.version }, encodedId: state.encodedId, audit: state.audit, operation: state.operation };
